'use strict';

const fs = require('node:fs');

const inputPath = 'ChatMachines/TokenizerCalibration/agents-by-header.json';
const outputPath = 'ChatMachines/TokenizerCalibration/agents-by-header-flattened.json';

function isObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function isContainer(value) {
  return Array.isArray(value) || isObject(value);
}

function decomposeObjectMembers(objectValue, wrap, atoms) {
  const keys = Object.keys(objectValue);
  if (keys.length === 0) {
    atoms.push(wrap({}));
    return;
  }

  for (const key of keys) {
    const child = objectValue[key];

    if (isObject(child)) {
      atoms.push(wrap({ [key]: {} }));
      if (Object.keys(child).length > 0) {
        decomposeObjectMembers(child, value => wrap({ [key]: value }), atoms);
      }
      continue;
    }

    if (Array.isArray(child)) {
      atoms.push(wrap({ [key]: [] }));
      if (child.length > 0) {
        decomposeArrayMembers(child, value => wrap({ [key]: value }), atoms);
      }
      continue;
    }

    atoms.push(wrap({ [key]: child }));
  }
}

function decomposeArrayMembers(arrayValue, wrap, atoms) {
  for (const member of arrayValue) {
    if (isObject(member)) {
      if (Object.keys(member).length === 0) {
        atoms.push(wrap([{}]));
      } else {
        decomposeObjectMembers(member, value => wrap([value]), atoms);
      }
      continue;
    }

    if (Array.isArray(member)) {
      if (member.length === 0) {
        atoms.push(wrap([[]]));
      } else {
        decomposeArrayMembers(member, value => wrap([value]), atoms);
      }
      continue;
    }

    atoms.push(wrap([member]));
  }
}

function flattenAtomicProjection(source) {
  const atoms = [];
  const identity = value => value;

  if (isObject(source)) {
    atoms.push({});
    decomposeObjectMembers(source, identity, atoms);
    return atoms;
  }

  if (Array.isArray(source)) {
    atoms.push([]);
    decomposeArrayMembers(source, identity, atoms);
    return atoms;
  }

  return [source];
}

function main() {
  const source = JSON.parse(fs.readFileSync(inputPath, 'utf8'));
  const flattened = flattenAtomicProjection(source);
  fs.writeFileSync(outputPath, JSON.stringify(flattened) + '\n', 'utf8');
  console.log(JSON.stringify({ input: inputPath, output: outputPath, atoms: flattened.length }));
}

if (require.main === module) main();

module.exports = { flattenAtomicProjection };

'use strict';

const fs = require('node:fs');
const path = require('node:path');

const model = process.env.GEMINI_MODEL || 'gemini-3.8-flash';
const agentsPath = 'ChatMachines/GeminiSupervisor/Agents.md';
const agentsHeaderJsonPath = 'ChatMachines/TokenizerCalibration/agents-by-header.json';
const agentsRoundTripPath = 'ChatMachines/TokenizerCalibration/agents-by-header-roundtrip.json';
const resultsPath = 'ChatMachines/TokenizerCalibration/tokenizer-results.json';

function agentsJsonByHeader(markdown) {
  const lines = markdown.split(/\r?\n/);
  const sections = [];
  let currentHeader = 'Agents.md';

  for (let i = 0; i < lines.length; i += 1) {
    const header = lines[i].match(/^#{1,6}\s+(.+?)\s*$/);
    if (header) {
      currentHeader = header[1];
      continue;
    }

    if (lines[i].trim() !== '```json') continue;

    const jsonLines = [];
    i += 1;
    while (i < lines.length && lines[i].trim() !== '```') {
      jsonLines.push(lines[i]);
      i += 1;
    }

    const jsonText = jsonLines.join('\n').trim();
    if (!jsonText) continue;

    let parsed;
    try {
      parsed = JSON.parse(jsonText);
    } catch (error) {
      throw new Error(`Invalid JSON under header "${currentHeader}": ${error.message}`);
    }

    sections.push({ [currentHeader]: parsed });
  }

  return sections;
}

async function exactCount(text) {
  const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:countTokens`;
  const response = await fetch(url, {
    method: 'POST',
    headers: {
      'x-goog-api-key': process.env.GEMINI_API_KEY,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      contents: [{ parts: [{ text }] }]
    })
  });

  if (!response.ok) {
    throw new Error(`countTokens ${response.status}: ${await response.text()}`);
  }

  const result = await response.json();
  return result.totalTokens;
}

async function measure(file) {
  const text = fs.readFileSync(file, 'utf8');
  const characters = text.length;
  const exactTokens = await exactCount(text);
  const div3 = Math.ceil(characters / 3);
  const div4 = Math.ceil(characters / 4);

  return {
    file,
    characters,
    exact_tokens: exactTokens,
    characters_per_token: Number((characters / exactTokens).toFixed(4)),
    ceil_chars_div_3: div3,
    div_3_error_tokens: div3 - exactTokens,
    div_3_error_percent: Number((((div3 - exactTokens) / exactTokens) * 100).toFixed(2)),
    ceil_chars_div_4: div4,
    div_4_error_tokens: div4 - exactTokens,
    div_4_error_percent: Number((((div4 - exactTokens) / exactTokens) * 100).toFixed(2))
  };
}

async function main() {
  const rawAgents = fs.readFileSync(agentsPath, 'utf8');
  const headerJson = agentsJsonByHeader(rawAgents);

  fs.mkdirSync(path.dirname(agentsHeaderJsonPath), { recursive: true });
  fs.writeFileSync(agentsHeaderJsonPath, JSON.stringify(headerJson) + '\n');

  const headerJsonText = fs.readFileSync(agentsHeaderJsonPath, 'utf8');
  const roundTripText = JSON.stringify(JSON.parse(headerJsonText));
  fs.writeFileSync(agentsRoundTripPath, roundTripText);

  const samples = [
    agentsPath,
    agentsHeaderJsonPath,
    agentsRoundTripPath,
    'ChatMachines/GeminiSupervisor/send-to-gemini.js',
    'ChatMachines/GeminiSupervisor/tests/step-3-evaluation.json'
  ];

  const results = [];
  for (const file of samples) results.push(await measure(file));

  const raw = results.find(item => item.file === agentsPath);
  const structured = results.find(item => item.file === agentsHeaderJsonPath);
  const roundTrip = results.find(item => item.file === agentsRoundTripPath);

  const output = {
    generated_at: new Date().toISOString(),
    model,
    agents_header_json: {
      sections: headerJson.length,
      raw_tokens: raw.exact_tokens,
      structured_tokens: structured.exact_tokens,
      token_change: structured.exact_tokens - raw.exact_tokens,
      token_change_percent: Number((((structured.exact_tokens - raw.exact_tokens) / raw.exact_tokens) * 100).toFixed(2))
    },
    exact_json_stringify_parse: {
      expression: 'JSON.stringify(JSON.parse(text))',
      input_file: agentsHeaderJsonPath,
      output_file: agentsRoundTripPath,
      input_characters: structured.characters,
      output_characters: roundTrip.characters,
      character_change: roundTrip.characters - structured.characters,
      input_tokens: structured.exact_tokens,
      output_tokens: roundTrip.exact_tokens,
      token_change: roundTrip.exact_tokens - structured.exact_tokens,
      token_change_percent: Number((((roundTrip.exact_tokens - structured.exact_tokens) / structured.exact_tokens) * 100).toFixed(4))
    },
    samples: results
  };

  fs.writeFileSync(resultsPath, JSON.stringify(output, null, 2) + '\n');
  console.log(JSON.stringify(output, null, 2));
}

main().catch(error => {
  console.error(error.stack || error.message || String(error));
  process.exit(1);
});

'use strict';

const fs = require('node:fs');
const path = require('node:path');

const repoRoot = path.resolve(process.cwd());
const model = process.env.GEMINI_MODEL || 'gemini-3.8-flash';
const maxTokens = 12000;
const outRoot = 'ChatMachines/TokenizerCalibration';
const batchesRoot = path.join(outRoot, 'stage1-batches');

const corpus = [
  { path: 'ChatMachines/GeminiSupervisor/config.json', classification: 'required', kind: 'json' },
  { path: 'ChatMachines/GeminiSupervisor/Agents.md', classification: 'required', kind: 'agents' },
  { path: 'ChatMachines/GeminiSupervisor/send-to-gemini.js', classification: 'required', kind: 'javascript' },
  { path: '.github/workflows/gemini-chat.yml', classification: 'required', kind: 'text' },
  { path: 'ChatMachines/GeminiSupervisor/nextmessage/nextmessage.json', classification: 'required', kind: 'json' },
  { path: 'ChatMachines/GeminiSupervisor/skills/live-ground-truth-verification/SKILL.md', classification: 'supporting', kind: 'text' },
  { path: 'ChatMachines/GeminiSupervisor/work-action-approval-rulebook.json', classification: 'supporting', kind: 'json' },
  { path: 'ChatMachines/GeminiSupervisor/dependency-map.json', classification: 'supporting', kind: 'json' },
  { path: 'ChatMachines/GeminiSupervisor/tests/step-3-evaluation.json', classification: 'supporting', kind: 'json' },
  { path: 'ChatMachines/GeminiSupervisor/MANIFEST.md', classification: 'supporting', kind: 'text' },
  { path: 'ChatMachines/GeminiSupervisor/runs/demo_20260930T155153_eadd5e5248/state.json', classification: 'optional_sample', kind: 'json' }
];

function readText(rel) {
  return fs.readFileSync(path.resolve(repoRoot, rel), 'utf8');
}

function agentsJsonByHeader(markdown) {
  const lines = markdown.split(/\r?\n/);
  const sections = [];
  let currentHeader = 'Agents.md';
  for (let i = 0; i < lines.length; i += 1) {
    const header = lines[i].match(/^#{1,6}\s+(.+?)\s*$/);
    if (header) {
      currentHeader = header[1];
      continue;
    }
    if (lines[i].trim() !== '```json') continue;
    const jsonLines = [];
    i += 1;
    while (i < lines.length && lines[i].trim() !== '```') {
      jsonLines.push(lines[i]);
      i += 1;
    }
    const text = jsonLines.join('\n').trim();
    if (text) sections.push({ [currentHeader]: JSON.parse(text) });
  }
  return sections;
}

function normalizeDocument(spec) {
  const raw = readText(spec.path);
  if (spec.kind === 'json') return JSON.stringify(JSON.parse(raw));
  if (spec.kind === 'agents') return JSON.stringify(agentsJsonByHeader(raw));
  return raw;
}

async function countTokens(text) {
  const response = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(model)}:countTokens`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'x-goog-api-key': process.env.GEMINI_API_KEY
    },
    body: JSON.stringify({ contents: [{ parts: [{ text }] }] })
  });
  const body = await response.text();
  if (!response.ok) throw new Error(`countTokens ${response.status}: ${body}`);
  const parsed = JSON.parse(body);
  return parsed.totalTokens;
}

function wrapped(pathName, classification, segment, content) {
  return { path: pathName, classification, segment, content };
}

function splitJs(text, spec) {
  const matches = [...text.matchAll(/^function\s+([A-Za-z_$][\w$]*)\s*\(/gm)];
  if (!matches.length) return [wrapped(spec.path, spec.classification, 'whole', text)];
  const units = [];
  if (matches[0].index > 0) {
    units.push(wrapped(spec.path, spec.classification, 'preamble', text.slice(0, matches[0].index)));
  }
  for (let i = 0; i < matches.length; i += 1) {
    const start = matches[i].index;
    const end = i + 1 < matches.length ? matches[i + 1].index : text.length;
    units.push(wrapped(spec.path, spec.classification, `function:${matches[i][1]}`, text.slice(start, end)));
  }
  return units;
}

function splitMarkdown(text, spec) {
  const matches = [...text.matchAll(/^#{1,6}\s+(.+)$/gm)];
  if (!matches.length) return [wrapped(spec.path, spec.classification, 'whole', text)];
  const units = [];
  if (matches[0].index > 0) units.push(wrapped(spec.path, spec.classification, 'preamble', text.slice(0, matches[0].index)));
  for (let i = 0; i < matches.length; i += 1) {
    const start = matches[i].index;
    const end = i + 1 < matches.length ? matches[i + 1].index : text.length;
    units.push(wrapped(spec.path, spec.classification, `heading:${matches[i][1].trim()}`, text.slice(start, end)));
  }
  return units;
}

async function splitJsonValue(value, spec, jsonPath = '$') {
  const candidate = wrapped(spec.path, spec.classification, jsonPath, JSON.stringify(value));
  if (await countTokens(JSON.stringify([candidate])) <= maxTokens) return [candidate];

  if (Array.isArray(value)) {
    if (value.length <= 1) throw new Error(`Unsplittable JSON array segment exceeds ${maxTokens} tokens: ${spec.path} ${jsonPath}`);
    const mid = Math.ceil(value.length / 2);
    return [
      ...(await splitJsonValue(value.slice(0, mid), spec, `${jsonPath}[0:${mid}]`)),
      ...(await splitJsonValue(value.slice(mid), spec, `${jsonPath}[${mid}:${value.length}]`))
    ];
  }

  if (value && typeof value === 'object') {
    const entries = Object.entries(value);
    if (!entries.length) throw new Error(`Unsplittable JSON object segment exceeds ${maxTokens} tokens: ${spec.path} ${jsonPath}`);
    if (entries.length === 1) {
      const [key, child] = entries[0];
      return splitJsonValue(child, spec, `${jsonPath}.${key}`);
    }
    const out = [];
    for (const [key, child] of entries) {
      out.push(...await splitJsonValue(child, spec, `${jsonPath}.${key}`));
    }
    return out;
  }

  throw new Error(`Unsplittable scalar exceeds ${maxTokens} tokens: ${spec.path} ${jsonPath}`);
}

async function splitOversizeText(unit) {
  const lines = unit.content.split(/(?<=\n)/);
  if (lines.length <= 1) throw new Error(`Unsplittable text segment exceeds ${maxTokens} tokens: ${unit.path} ${unit.segment}`);
  const out = [];
  let current = '';
  let part = 0;
  for (const line of lines) {
    const proposed = current + line;
    const probe = wrapped(unit.path, unit.classification, `${unit.segment}:part-${part}`, proposed);
    if (current && await countTokens(JSON.stringify([probe])) > maxTokens) {
      out.push(wrapped(unit.path, unit.classification, `${unit.segment}:part-${part}`, current));
      part += 1;
      current = line;
    } else {
      current = proposed;
    }
  }
  if (current) out.push(wrapped(unit.path, unit.classification, `${unit.segment}:part-${part}`, current));
  return out;
}

async function initialUnits(spec, content) {
  const whole = wrapped(spec.path, spec.classification, 'whole', content);
  if (await countTokens(JSON.stringify([whole])) <= maxTokens) return [whole];

  if (spec.kind === 'agents') {
    const sections = JSON.parse(content);
    const out = [];
    for (let i = 0; i < sections.length; i += 1) {
      const key = Object.keys(sections[i])[0] || `section-${i}`;
      out.push(wrapped(spec.path, spec.classification, `header:${key}`, JSON.stringify(sections[i])));
    }
    return out;
  }

  if (spec.kind === 'json') return splitJsonValue(JSON.parse(content), spec);

  const structural = spec.kind === 'javascript' ? splitJs(content, spec) : splitMarkdown(content, spec);
  const out = [];
  for (const unit of structural) {
    if (await countTokens(JSON.stringify([unit])) <= maxTokens) out.push(unit);
    else out.push(...await splitOversizeText(unit));
  }
  return out;
}

async function pack(units) {
  const batches = [];
  let current = [];
  for (const unit of units) {
    const singletonTokens = await countTokens(JSON.stringify([unit]));
    if (singletonTokens > maxTokens) throw new Error(`Unit still exceeds max_tokens: ${unit.path} ${unit.segment} = ${singletonTokens}`);
    const candidate = [...current, unit];
    const candidateTokens = await countTokens(JSON.stringify(candidate));
    if (current.length && candidateTokens > maxTokens) {
      const currentTokens = await countTokens(JSON.stringify(current));
      batches.push({ units: current, tokens: currentTokens });
      current = [unit];
    } else {
      current = candidate;
    }
  }
  if (current.length) batches.push({ units: current, tokens: await countTokens(JSON.stringify(current)) });
  return batches;
}

async function main() {
  if (!process.env.GEMINI_API_KEY) throw new Error('GEMINI_API_KEY is missing.');

  const docs = [];
  const allUnits = [];
  for (const spec of corpus) {
    if (!fs.existsSync(path.resolve(repoRoot, spec.path))) throw new Error(`Corpus file missing: ${spec.path}`);
    const content = normalizeDocument(spec);
    const serialized = JSON.stringify({ path: spec.path, classification: spec.classification, content });
    const tokens = await countTokens(serialized);
    docs.push({ path: spec.path, classification: spec.classification, kind: spec.kind, characters: content.length, wrapped_tokens: tokens });
    allUnits.push(...await initialUnits(spec, content));
  }

  const serializedCorpus = JSON.stringify(corpus.map((spec, i) => ({
    path: spec.path,
    classification: spec.classification,
    content: normalizeDocument(spec)
  })));
  const totalTokens = await countTokens(serializedCorpus);
  const batches = await pack(allUnits);

  fs.rmSync(batchesRoot, { recursive: true, force: true });
  fs.mkdirSync(batchesRoot, { recursive: true });
  batches.forEach((batch, index) => {
    fs.writeFileSync(path.join(batchesRoot, `B0-b${index}.json`), JSON.stringify(batch.units) + '\n');
  });

  const analysis = {
    generated_at: new Date().toISOString(),
    model,
    max_tokens: maxTokens,
    corpus_policy: {
      send_to_gemini: 'current repository source, unminified',
      agents_md: 'header-keyed JSON representation, JSON.stringify(JSON.parse(text)) equivalent',
      json_files: 'JSON.stringify(JSON.parse(text))',
      other_text_files: 'original text',
      code_gs: 'excluded because no current active dependency was established',
      optional_sample: 'included'
    },
    total_serialized_corpus_tokens: totalTokens,
    sum_individual_wrapped_document_tokens: docs.reduce((sum, d) => sum + d.wrapped_tokens, 0),
    documents: docs,
    B0: {
      batch_count: batches.length,
      batches: batches.map((batch, index) => ({
        b: index,
        tokens: batch.tokens,
        unit_count: batch.units.length,
        units: batch.units.map(u => ({ path: u.path, classification: u.classification, segment: u.segment }))
      }))
    }
  };

  fs.writeFileSync(path.join(outRoot, 'stage1-corpus-analysis.json'), JSON.stringify(analysis, null, 2) + '\n');
  console.log(JSON.stringify(analysis, null, 2));
}

main().catch(error => {
  console.error(error.stack || error.message || String(error));
  process.exit(1);
});

const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');

function safeFilenamePart(value) {
  return value
    .normalize('NFKD')
    .replace(/[\\/:*?"<>|]+/g, '-')
    .replace(/[^a-zA-Z0-9._ -]+/g, '')
    .trim()
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^[-_.]+|[-_.]+$/g, '')
    .slice(0, 120) || 'shared-chat';
}

function extractionTimestamp(now = new Date()) {
  return now.toISOString().replace(/:/g, '-');
}

function extractSharedChat(htmlPath, outputDir) {
  if (!fs.existsSync(htmlPath)) {
    throw new Error(`Input HTML file not found: ${htmlPath}`);
  }

  const html = fs.readFileSync(htmlPath, 'utf8');
  const enqueuedChunks = [];

  const scriptRegex = /<script\b[^>]*>([\s\S]*?)<\/script>/gi;
  const context = {
    window: {
      __reactRouterContext: {
        streamController: {
          enqueue(chunk) {
            enqueuedChunks.push(chunk);
          },
          close() {}
        }
      }
    }
  };
  vm.createContext(context);

  let match;
  while ((match = scriptRegex.exec(html)) !== null) {
    const scriptContent = match[1];
    if (scriptContent.includes('streamController.enqueue')) {
      try {
        vm.runInContext(scriptContent, context);
      } catch (err) {
        // Fallback handled below.
      }
    }
  }

  if (enqueuedChunks.length === 0) {
    const marker = '.streamController.enqueue(';
    let cursor = 0;
    while (true) {
      const start = html.indexOf(marker, cursor);
      if (start === -1) break;
      const argStart = start + marker.length;
      let argEnd = html.indexOf(');\n</script>', argStart);
      if (argEnd === -1) argEnd = html.indexOf(');</script>', argStart);
      if (argEnd !== -1) {
        const rawArg = html.slice(argStart, argEnd).trim();
        try {
          const parsed = vm.runInNewContext(rawArg);
          enqueuedChunks.push(parsed);
        } catch {
          try {
            enqueuedChunks.push(JSON.parse(rawArg));
          } catch {}
        }
      }
      cursor = argStart + 1;
    }
  }

  const mainPayloadStr = enqueuedChunks.find(
    chunk => typeof chunk === 'string' && chunk.trim().startsWith('[')
  );

  if (!mainPayloadStr) {
    throw new Error('Could not find serialized React Router / turbo-stream payload in HTML');
  }

  const raw = JSON.parse(mainPayloadStr.trim());
  if (!Array.isArray(raw)) {
    throw new Error('Expected parsed turbo-stream payload to be a flat array');
  }

  const cache = new Map();

  function decode(slot) {
    if (slot === -5 || slot === -1) return undefined;
    if (slot === -2) return NaN;
    if (slot === -3) return Infinity;
    if (slot === -4) return -Infinity;
    if (typeof slot !== 'number' || slot < 0 || slot >= raw.length) {
      return slot;
    }
    if (cache.has(slot)) {
      return cache.get(slot);
    }

    const item = raw[slot];
    if (item === null || typeof item !== 'object') {
      cache.set(slot, item);
      return item;
    }

    if (Array.isArray(item)) {
      if (item.length === 2 && item[0] === 'P') {
        const prom = { __promise: item[1] };
        cache.set(slot, prom);
        return prom;
      }
      if (item.length === 2 && item[0] === 'D') {
        const date = new Date(item[1]);
        cache.set(slot, date);
        return date;
      }
      const arr = [];
      cache.set(slot, arr);
      for (let i = 0; i < item.length; i++) {
        arr.push(decode(item[i]));
      }
      return arr;
    }

    const obj = {};
    cache.set(slot, obj);
    for (const [k, vSlot] of Object.entries(item)) {
      let propName;
      if (k.startsWith('_')) {
        const keyIdx = parseInt(k.slice(1), 10);
        propName = raw[keyIdx];
      } else {
        propName = k;
      }
      const propVal = decode(vSlot);
      if (propName !== undefined && propVal !== undefined) {
        obj[propName] = propVal;
      }
    }
    return obj;
  }

  const root = decode(0);

  let conversation = root?.loaderData?.['routes/share.$shareId.($action)']?.serverResponse?.data;

  if (!conversation) {
    const visited = new Set();
    function findConvo(target, depth = 0) {
      if (!target || typeof target !== 'object' || depth > 8 || visited.has(target)) return null;
      visited.add(target);
      if (target.conversation_id && (target.mapping || target.linear_conversation)) {
        return target;
      }
      for (const val of Object.values(target)) {
        const found = findConvo(val, depth + 1);
        if (found) return found;
      }
      return null;
    }
    conversation = findConvo(root);
  }

  if (!conversation) {
    throw new Error('Decoded stream data did not yield a valid shared conversation object');
  }

  if (typeof conversation.title !== 'string' || conversation.title.length === 0) {
    throw new Error(`Validation failed: missing title in conversation (got ${conversation.title})`);
  }
  if (typeof conversation.conversation_id !== 'string' || conversation.conversation_id.length === 0) {
    throw new Error('Validation failed: missing conversation_id');
  }
  if (!conversation.mapping || typeof conversation.mapping !== 'object') {
    throw new Error('Validation failed: conversation.mapping is not an object');
  }
  const mappingKeys = Object.keys(conversation.mapping);
  if (mappingKeys.length === 0) {
    throw new Error('Validation failed: conversation.mapping contains 0 message nodes');
  }
  if (!Array.isArray(conversation.linear_conversation) || conversation.linear_conversation.length === 0) {
    throw new Error('Validation failed: linear_conversation is missing or empty');
  }

  const sampleNode = conversation.linear_conversation.find(n => n?.message?.author?.role);
  if (!sampleNode) {
    throw new Error('Validation failed: no message nodes with author.role found');
  }

  const filename = `${safeFilenamePart(conversation.title)}__${extractionTimestamp()}.json`;
  const outJsonPath = path.resolve(outputDir, filename);

  fs.mkdirSync(outputDir, { recursive: true });
  fs.writeFileSync(outJsonPath, JSON.stringify(conversation, null, 2) + '\n', 'utf8');

  console.log('Successfully extracted shared conversation:');
  console.log(`- Title: "${conversation.title}"`);
  console.log(`- Conversation ID: ${conversation.conversation_id}`);
  console.log(`- Mapping nodes: ${mappingKeys.length}`);
  console.log(`- Linear conversation turns: ${conversation.linear_conversation.length}`);
  console.log(`- Model: ${conversation.default_model_slug || 'N/A'}`);
  console.log(`- Written to: ${outJsonPath}`);

  return outJsonPath;
}

const inputHtml = path.resolve('untrusted AI/shared-chat-page.html');
const outputDir = path.resolve('untrusted AI');
const outputJson = extractSharedChat(inputHtml, outputDir);

if (process.env.GITHUB_OUTPUT) {
  const relativeOutput = path.relative(process.cwd(), outputJson);
  fs.appendFileSync(process.env.GITHUB_OUTPUT, `json_path=${relativeOutput}\n`, 'utf8');
}
